import { Pipe, PipeTransform } from '@angular/core';
import { Ingredient } from '../services/cart.service';

@Pipe({
  name: 'ingredientTotal'
})
export class IngredientTotalPipe implements PipeTransform {

  transform(ingredients: Ingredient[] | undefined): number {

    if (!ingredients) {
      return 0;
    }

    return ingredients.reduce(
      (total, ingredient) =>
        total + ingredient.price,
      0
    );

  }

}
